python
def ribbonRunsFirstQualifyingSlip(line, k):
    a=line
    out=[]
    i=0
    while i<len(a):
        j=i+1
        while j<len(a) and a[j]==a[i]: j+=1
        out.append(j-i)
        i=j
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int ribbonRunsFirstQualifyingSlip(String line, int k) {
    String a=line; List<Integer> out=new ArrayList<>();
    {for(int i=0;i<a.length();){int j=i+1;while(j<a.length()&&a.charAt(j)==a.charAt(i))j++;out.add(j-i);i=j;}}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
